const txt = $('Validate_Message_And_Intent1').first().json.userMessage?.toLowerCase() || '';
const originalMessage = $('Validate_Message_And_Intent1').first().json.userMessage || '';
const updates = {};

const namePatterns = [
  /(?:my name is|i am|i'm|this is|naam hai)\s+([a-zA-Z\s]{2,30})/i,
  /(?:student name|child name|son name|daughter name)\s*:?\s*([a-zA-Z\s]{2,30})/i
];
for (const pattern of namePatterns) {
  const match = originalMessage.match(pattern);
  if (match && match[1]) {
    updates.student_name = match[1].trim();
    break;
  }
}

const classPatterns = [
  /class\s+(\d{1,2})/i,
  /grade\s+(\d{1,2})/i,
  /(\d{1,2})(?:th|st|nd|rd)\s+(?:class|grade|standard)/i,
  /studying\s+in\s+(\d{1,2})/i
];
for (const pattern of classPatterns) {
  const match = originalMessage.match(pattern);
  if (match && match[1]) {
    updates.class = match[1];
    break;
  }
}

if (/\b(jee|joint entrance|iit entrance)\b/i.test(txt)) updates.exam_goal = 'JEE';
if (/\b(neet|medical entrance|mbbs)\b/i.test(txt)) updates.exam_goal = 'NEET';
if (/\b(iit)\b/i.test(txt)) updates.college_preference = 'IIT';
if (/\b(nit|national institute)\b/i.test(txt)) updates.college_preference = 'NIT';
if (/\b(aiims)\b/i.test(txt)) updates.college_preference = 'AIIMS';
if (/\b(engineering|engineer)\b/i.test(txt)) updates.career_interest = 'Engineering';
if (/\b(doctor|medicine|medical)\b/i.test(txt)) updates.career_interest = 'Medicine';

if (/\bcbse\b/i.test(txt)) updates.board = 'CBSE';
if (/\bicse\b/i.test(txt)) updates.board = 'ICSE';
if (/\bstate\s+board\b/i.test(txt)) updates.board = 'State Board';

if (/\b(science|pcm|pcb|biology|physics)\b/i.test(txt)) updates.stream = 'Science';
if (/\b(commerce|accounts|business)\b/i.test(txt)) updates.stream = 'Commerce';
if (/\b(arts|humanities)\b/i.test(txt)) updates.stream = 'Arts';

const subjects = [];
if (/\bmaths?\b|mathematics/i.test(txt)) subjects.push('Maths');
if (/\bphysics\b/i.test(txt)) subjects.push('Physics');
if (/\bchemistry\b/i.test(txt)) subjects.push('Chemistry');
if (/\bbiology\b/i.test(txt)) subjects.push('Biology');
if (/\benglish\b/i.test(txt)) subjects.push('English');
if (subjects.length > 0) updates.subjects_of_interest = subjects;

if (/\b(budget|afford|expensive|costly|cheap|price|fees?)\b/i.test(txt)) {
  updates.budget_conscious = true;
  if (/\blow\s+budget|can't afford|tight budget/i.test(txt)) {
    updates.budget_level = 'low';
  } else if (/\breasonable|moderate/i.test(txt)) {
    updates.budget_level = 'medium';
  }
}

if (/\b(urgent|immediately|asap|right now|soon|this week)\b/i.test(txt)) {
  updates.timeline_urgency = 'high';
} else if (/\b(next month|planning|thinking|considering)\b/i.test(txt)) {
  updates.timeline_urgency = 'low';
}

const locationPatterns = [
  /(?:from|live in|located in|staying in|at|near)\s+([A-Z][a-zA-Z\s]{3,20})(?:\s|,|\.|$)/,
  /([A-Z][a-zA-Z]{3,15})\s+(?:area|locality|colony|nagar|road|street)\b/
];

const locationExclusions = ['Class', 'Grade', 'The', 'My', 'Our', 'Your', 'This', 'That', 'Standard', 'Board', 'School', 'College'];

for (const pattern of locationPatterns) {
  const match = originalMessage.match(pattern);
  if (match && match[1]) {
    const location = match[1].trim();
    if (!locationExclusions.includes(location) && !/\d/.test(location) && location.length > 2) {
      updates.location = location;
      break;
    }
  }
}

const weaknesses = [];
if (/\bweak\s+in\s+(maths?|physics|chemistry|biology|english)/i.test(txt)) {
  const match = txt.match(/weak\s+in\s+(maths?|physics|chemistry|biology|english)/i);
  if (match) weaknesses.push(match[1]);
}
if (/\bstruggling\s+with\s+(maths?|physics|chemistry|biology|english)/i.test(txt)) {
  const match = txt.match(/struggling\s+with\s+(maths?|physics|chemistry|biology|english)/i);
  if (match) weaknesses.push(match[1]);
}
if (weaknesses.length > 0) updates.weak_subjects = weaknesses;

const concerns = [];
if (/\bexam\s+(?:pressure|stress|anxiety)/i.test(txt)) concerns.push('exam_stress');
if (/\bperformance|marks|grades|score/i.test(txt)) concerns.push('academic_performance');
if (/\bfocus|concentration|distraction/i.test(txt)) concerns.push('focus_issues');
if (/\bconfidence|self-esteem/i.test(txt)) concerns.push('confidence');
if (concerns.length > 0) updates.parent_concerns = concerns;

if (/\b(attended|joined|taking|going to)\s+(?:coaching|tuition|classes)/i.test(txt)) {
  updates.has_previous_coaching = true;
}

if (/\b(starting|begin|start|new to)/i.test(txt)) updates.prep_stage = 'beginner';
if (/\b(preparing|studying for)/i.test(txt)) updates.prep_stage = 'ongoing';
if (/\b(exam in|appearing in|taking exam)/i.test(txt)) updates.prep_stage = 'advanced';

if (Object.keys(updates).length > 0) {
  const existingProfile = $('Validate_Message_And_Intent1').first().json.profile || {};

  const arrayFields = ['subjects_of_interest', 'weak_subjects', 'parent_concerns'];
  const multiValueFields = ['exam_goal', 'college_preference', 'career_interest'];

  for (const field of arrayFields) {
    if (updates[field] && Array.isArray(updates[field])) {
      const existing = existingProfile[field] || [];
      updates[field] = [...new Set([...existing, ...updates[field]])];
    }
  }

  for (const field of multiValueFields) {
    if (updates[field]) {
      let newValues = Array.isArray(updates[field]) ? updates[field] : [updates[field]];
      let existing = existingProfile[field];

      if (existing && !Array.isArray(existing)) {
        existing = [existing];
      } else if (!existing) {
        existing = [];
      }

      updates[field] = [...new Set([...existing, ...newValues])];
    }
  }

  return {
    json: {
      hasUpdates: true,
      lead_id_input: $('Validate_Message_And_Intent1').first().json.lead_id,
      memory_type: 'profile',
      content_input: updates
    }
  };
} else {
  return {
    json: {
      hasUpdates: false
    }
  };
}

try {
  const userSave = $('Save_User_Message1').first().json;
  const aiSave = $('Save_AI_Message1').first().json;
  const aiData = $('Extract_AI_Response1').first().json;

  let saveStatus = 'full_success';
  let errorDetails = [];

  if (!userSave || !userSave.success) {
    console.error('❌ User message save failed:', userSave);
    saveStatus = 'partial_failure';
    errorDetails.push('user_message_not_saved');
  }

  if (!aiSave || !aiSave.success) {
    console.error('❌ AI message save failed:', aiSave);
    saveStatus = 'partial_failure';
    errorDetails.push('ai_message_not_saved');
  }

  if (saveStatus === 'full_success') {
    console.log('✅ Both messages saved successfully');
  } else {
    console.warn('⚠️ Partial save failure:', errorDetails.join(', '));
  }

  return {
    json: {
      success: saveStatus === 'full_success',
      save_status: saveStatus,
      error_details: errorDetails,
      user_message_id: userSave?.message_id || null,
      ai_message_id: aiSave?.message_id || null,
      session_id: aiData?.session_id || null,
      should_end_session: aiData?.should_end_session || false,
      ai_response: aiData?.ai_response || 'Error retrieving response',
      lead_phone: aiData?.lead_phone || '',
      lead_id: aiData?.lead_id || ''
    }
  };
} catch (error) {
  console.error('🔥 CRITICAL ERROR in Verify_Messages_Saved:', error.message);
  const aiData = $('Extract_AI_Response1').first()?.json || {};
  return {
    json: {
      success: false,
      save_status: 'error',
      error_details: ['verification_error', error.message],
      user_message_id: null,
      ai_message_id: null,
      session_id: aiData.session_id || null,
      should_end_session: aiData.should_end_session || false,
      ai_response: aiData.ai_response || 'Error',
      lead_phone: aiData.lead_phone || '',
      lead_id: aiData.lead_id || ''
    }
  };
}

const aiResponse = $json;
let aiText = '';

function extractText(obj, depth = 0) {
  if (depth > 5) return null;

  if (typeof obj === 'string') {
    return obj;
  }

  if (Array.isArray(obj)) {
    for (const item of obj) {
      if (typeof item === 'string') {
        return item;
      }
      if (item?.type === 'text' && item?.text) {
        return item.text;
      }
      if (item?.text) {
        return item.text;
      }
      const nested = extractText(item, depth + 1);
      if (nested) return nested;
    }
  }

  if (typeof obj === 'object' && obj !== null) {
    const fields = ['output', 'text', 'response', 'message', 'content', 'result', 'answer'];
    for (const field of fields) {
      if (obj[field]) {
        const extracted = extractText(obj[field], depth + 1);
        if (extracted) return extracted;
      }
    }
  }

  return null;
}

aiText = extractText(aiResponse) || '';

if (!aiText || aiText.trim().length === 0) {
  try {
    const jsonStr = JSON.stringify(aiResponse);
    const patterns = [
      /"(?:output|text|response|message|content|result|answer)"\s*:\s*"([^"]{10,})"/i,
      /"text"\s*:\s*"([^"]+)"/i,
      /:\s*"([^"]{20,})"/
    ];

    for (const pattern of patterns) {
      const match = jsonStr.match(pattern);
      if (match && match[1] && match[1].length > 5) {
        aiText = match[1];
        break;
      }
    }
  } catch (e) {
    console.error('Regex extraction failed:', e);
  }
}

if (!aiText || aiText.trim().length === 0) {
  aiText = 'I apologize, I\'m having technical difficulties. Please try again or contact support.';
  console.error('CRITICAL: AI Agent output completely unreadable:', JSON.stringify(aiResponse, null, 2));
}

aiText = aiText
  .replace(/\\n/g, '\n')
  .replace(/\\t/g, '\t')
  .replace(/\\'/g, "'")
  .replace(/\\"/g, '"')
  .replace(/\\r/g, '')
  .trim();

if (aiText.length < 3) {
  aiText = 'I apologize, could you please rephrase that?';
}

const contextData = $('Validate_Message_And_Intent1').first().json;

return {
  json: {
    lead_id: contextData.lead_id,
    lead_phone: contextData.lead_phone,
    session_id: contextData.session_id,
    user_message: contextData.userMessage,
    user_role: contextData.detected_role,
    user_language: contextData.language,
    ai_response: aiText,
    timestamp: contextData.timestamp,
    should_end_session: contextData.should_end_session,
    extraction_successful: aiText.length >= 10
  }
};

